\label{thm:main}
Assume the true-function source, finite localisation and uniform
first-contact premises \textup{(A1)--(A3)} of
Section~\ref{sec:premises}. With the two complete source providers refined in
Section~\ref{sec:exponent}, and the 57 fixed kernels specified in
Appendix~\ref{app:kernels}, the directed comparison of
Section~\ref{sec:certificate} gives
\begin{equation}\label{eq:main}
 \boxed{\Lambda\le\frac{148611789321711}{10^{15}}
              =0.148611789321711<0.148612.}
\end{equation}
No hypothesis \(\mathsf H_\alpha\), with \(\alpha<1\), concerning a fixed
zero-free half-plane for the Riemann zeta function is used.

\label{lem:dynamics}
At such a simple zero, with \(q=y^2\),
\begin{equation}\label{eq:dynamics}
 q'=-2-4y\sum_{\mathrm{other\ pairs}}K_y(x-a,b)
    =-2-4q\,G_t,\qquad
 G_t=\frac1y\sum_{\mathrm{other\ pairs}}K_y(x-a,b)\ge0.
\end{equation}
The imaginary parts of the paired zero sums converge absolutely.

\label{prop:rate}
Suppose \(\bar S_{t,h,r}(x)>\ell\) on the full contact domain and
\(q\le\rho^2h^2\). If the cap above is valid and
\[
 c=\frac{2\lambda}{h}\left(\ell-\frac Mh\right)>0,
\]
then at a simple highest-zero contact
\begin{equation}\label{eq:rate}
 q'<-2-cq.
\end{equation}

\label{prop:tail}
Assume \eqref{eq:decomposition}--\eqref{eq:matching} and
\(g=1-\bar A_0-\eta>0\). Then
\begin{equation}\label{eq:tailbound}
 \boxed{\operatorname{Re}\frac VQ\le
       \frac{\bar B_0+\nu\eta+\varepsilon-2Z_J}{1-\bar A_0-\eta}
              -(D_K-\operatorname{Re} T).}
\end{equation}
The bounds must hold uniformly on the full physical rectangle where
this source will be consumed.
